INSERT INTO "product_Chef" VALUES(1,'Ellie Krieger',5,'A warm, nutrition-focused chef who builds colourful meals around balance, fresh ingredients, and comfort. Her dishes feel light, practical, and full of everyday flavour.','Nutrition-Focused Chef','Healthy Recipe Developer','Balanced Cooking Expert','chefImage/ellie-krieger.png','ellie.krieger@loop.test','+44 (0)20 1001 0001');
INSERT INTO "product_Chef" VALUES(2,'Paul Rankin',5,'A classic chef with a confident bakery and bistro style, known for hearty plates, careful technique, and food that feels generous without becoming heavy.','Classic Technique Chef','Bakery Specialist','Comfort Food Mentor','chefImage/paul-rankin.png','paul.rankin@loop.test','+44 (0)20 1001 0002');
INSERT INTO "product_Chef" VALUES(3,'George R. R. Martin',5,'A storyteller-chef inspired by feast tables, slow-cooked comfort, and dramatic flavour. His menus lean rich, rustic, and memorable, with a little theatre in every plate.','Storytelling Chef','Rustic Feast Designer','Slow-Cook Specialist','chefImage/george-rr-martin.png','george.martin@loop.test','+44 (0)20 1001 0003');
INSERT INTO "product_Chef" VALUES(4,'Levy Rozman',5,'A precise and strategic chef who treats every dish like a smart move. His meals are balanced, cleanly built, and designed with playful attention to detail.','Strategic Menu Planner','Precision Chef','Creative Kitchen Thinker','chefImage/levy-rozman.png','levy.rozman@loop.test','+44 (0)20 1001 0004');
INSERT INTO "product_Chef" VALUES(5,'Jamie Oliver',5,'A relaxed, family-style chef focused on fresh produce, simple methods, and food that feels lively. His meals are bright, approachable, and made for sharing.','Family Food Chef','Fresh Produce Advocate','Simple Cooking Teacher','chefImage/jamie-oliver.png','jamie.oliver@loop.test','+44 (0)20 1001 0005');
INSERT INTO "product_Chef" VALUES(6,'Mr Beast',5,'A high-energy chef personality who creates bold comfort meals with a fun, generous style. His plates are crowd-friendly, fast-moving, and built to satisfy.','High-Energy Chef','Crowd Meal Creator','Comfort Food Host','chefImage/mr-beast.png','mr.beast@loop.test','+44 (0)20 1001 0006');
INSERT INTO "product_Chef" VALUES(7,'Salt Bae',5,'A theatrical grill chef known for dramatic presentation, rich seasoning, and premium steakhouse energy. His dishes focus on confidence, aroma, and bold finish.','Grill Performance Chef','Seasoning Specialist','Steakhouse Presenter','chefImage/salt-bae.png','salt.bae@loop.test','+44 (0)20 1001 0007');
INSERT INTO "product_Chef" VALUES(8,'Guga Foods',5,'A meat and experiment focused chef who tests methods, marinades, and textures with curiosity. His meals are rich, smoky, and built around flavour discovery.','Grill Experiment Chef','Protein Specialist','Technique Tester','chefImage/guga-foods.png','guga.foods@loop.test','+44 (0)20 1001 0008');
INSERT INTO "product_Chef" VALUES(9,'Uncle Roger',5,'A playful Asian food specialist with strong opinions on rice, wok flavour, and proper seasoning. His cooking is comforting, expressive, and full of character.','Asian Food Critic Chef','Rice Technique Expert','Wok Flavour Specialist','chefImage/uncle-roger.png','uncle.roger@loop.test','+44 (0)20 1001 0009');
INSERT INTO "product_Chef" VALUES(10,'Nick DiGiovanni',5,'A modern chef with polished technique and creative curiosity, blending restaurant discipline with fun ideas. His dishes feel sharp, clean, and camera-ready.','Modern Technique Chef','Recipe Developer','Professional Kitchen Talent','chefImage/nick-digiovanni.png','nick.digiovanni@loop.test','+44 (0)20 1001 0010');
INSERT INTO "product_Chef" VALUES(11,'Gordon Ramsey',5,'A direct, high-standard chef focused on strong technique, refined comfort food, and confident seasoning. His meals are structured, bold, and full of precision.','Master Chef Mentor','Classic Technique Leader','High-Standard Kitchen Coach','chefImage/gordon-ramsey.png','gordon.ramsey@loop.test','+44 (0)20 1001 0011');
INSERT INTO "product_Chef" VALUES(12,'Zear Ibrahim',5,'A creative culinary expert blending traditional Asian techniques with contemporary health-focused recipes. Committed to delivering meals rich in taste while maintaining nutritional balance.','Asian Technique Chef','Health-Driven Creator','Experienced Culinary Mentor','chefImage/zear-ibrahim.png','zear.ibrahim@brunel.ac.uk','+44 (0)1895 268574');
INSERT INTO "product_Chef" VALUES(13,'Jasper Khant',5,'A thoughtful young chef with a clean Asian comfort style, balancing familiar flavours with modern presentation. His food is practical, warm, and carefully detailed.','Student Chef Creator','Asian Comfort Specialist','Balanced Flavour Planner','chefImage/jasper-khant.png','jasper.khant@brunel.ac.uk','+44 (0)20 1001 0013');
INSERT INTO "product_Chef" VALUES(14,'Alaa Marshan',5,'A calm and careful chef focused on balanced plates, dependable technique, and gentle flavour. His meals lean fresh, tidy, and suitable for everyday eating.','Careful Kitchen Chef','Balanced Plate Planner','Fresh Cooking Guide','chefImage/alaa-marshan.png','alaa.marshan@brunel.ac.uk','+44 (0)20 1001 0014');
INSERT INTO "product_Chef" VALUES(15,'Marcus Samuelsson',5,'A globally inspired chef blending heritage, spice, and modern restaurant energy. His cooking feels colourful, soulful, and layered with cultural flavour.','Global Cuisine Chef','Heritage Food Specialist','Award-Winning Mentor','chefImage/marcus-samuelsson.png','marcus.samuelsson@loop.test','+44 (0)20 1001 0015');
