INSERT INTO "product_Products" VALUES(29,'Chicken Satay Noodles','Chicken Satay Noodles is a freshly prepared Southeast Asian noodle dish built around grilled chicken, noodles, peanut satay sauce, vegetables, and herbs. It balances nutty sauce, smoky chicken, and a rich savoury noodle base, giving customers a complete meal with clear ingredients, satisfying texture, and dependable everyday nutrition.','Chicken Satay Noodles is designed as a complete Southeast Asian noodle dish rather than a small side or simple snack. The dish brings together grilled chicken, noodles, peanut satay sauce, vegetables, and herbs, then supports them with nutty sauce, smoky chicken, and a rich savoury noodle base. Each portion is planned to feel filling without becoming heavy, with enough protein, grains, or vegetables to give the meal structure and useful energy. The flavours stay recognisable, the ingredients are easy to understand, and the presentation fits the restaurant''s warm comfort-food style. Customers can still customise the base, protein, add-ons, spice level, and portion size while keeping the original character of the product intact.',4.1,10.49,1,2,'Malaysia','2026-06-22 00:00:00','2026-06-22 00:00:00',11,'product',100);
