BEGIN TRANSACTION;
CREATE TABLE customer_ChefReviews(reviewID TEXT PRIMARY KEY,customerID TEXT NOT NULL,chefID TEXT NOT NULL,rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5),reviewText TEXT NOT NULL,createdAt TEXT NOT NULL,FOREIGN KEY(customerID) REFERENCES customer_Customers(customerID),FOREIGN KEY(chefID) REFERENCES customer_Chefs(chefID),UNIQUE(customerID,chefID));
CREATE TABLE customer_Chefs(chefID TEXT PRIMARY KEY,chefName TEXT NOT NULL,speciality TEXT,averageRating REAL DEFAULT 0);
CREATE TABLE customer_CustomerPreference(preferenceID TEXT PRIMARY KEY,customerID TEXT NOT NULL,favoriteCategories TEXT,notificationSettings TEXT,deliveryInstructions TEXT,FOREIGN KEY(customerID) REFERENCES customer_Customers(customerID));
CREATE TABLE customer_Customers(customerID TEXT PRIMARY KEY,personID TEXT NOT NULL,deliveryAddress TEXT NOT NULL,idCardNo TEXT UNIQUE NOT NULL,idCardImagePath TEXT,status TEXT NOT NULL DEFAULT 'Active',FOREIGN KEY(personID) REFERENCES customer_People(personID));
CREATE TABLE customer_People(personID TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,mobile TEXT NOT NULL,passwordHash TEXT NOT NULL);
CREATE TABLE "delivery_AllDeliveries" (
	"DeliveryId"	TEXT,
	"OderId"	INTEGER,
	"Customer"	TEXT,
	"CusId"	INTEGER,
	"Total"	INTEGER,
	"Status"	TEXT,
	"Driver"	TEXT,
	"Action"	TEXT,
	PRIMARY KEY("DeliveryId","OderId")
);
CREATE TABLE "delivery_DeliveryDetails" (
	"DeliveryId"	TEXT,
	"CustomerName"	TEXT,
	"CustomerAddress"	INTEGER
);
');
