');
');
CREATE TABLE finance_Users(UserID INTEGER PRIMARY KEY AUTOINCREMENT,Email TEXT UNIQUE,PasswordHash TEXT);
CREATE TABLE inventory_Stock (
    stockYear INTEGER NOT NULL,
    stockCode TEXT NOT NULL,
    ingredientID INTEGER NOT NULL,
    stockQuantity INTEGER NOT NULL DEFAULT 0,
    warehouseID TEXT,
    capacity INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY (stockYear, stockCode),
    FOREIGN KEY (ingredientID) REFERENCES product_Ingredient(ingredientID)
        ON UPDATE CASCADE ON DELETE RESTRICT
);
CREATE TABLE "inventory_stock_TransactionLog" (
	"logID"	INTEGER,
	"username"	TEXT,
	"action"	TEXT,
	"details"	TEXT,
	"dateTime"	TEXT,
	PRIMARY KEY("logID" AUTOINCREMENT)
);
CREATE TABLE "inventory_stock_analytics" (
	"product"	TEXT NOT NULL,
	"locations"	TEXT NOT NULL,
	"currentQuantity"	INTEGER NOT NULL,
	"minThreshold"	INTEGER NOT NULL,
	"status"	TEXT NOT NULL,
	"lastRestock"	TEXT NOT NULL,
	"daysUntilReorder"	INTEGER NOT NULL,
	PRIMARY KEY("product")
);
CREATE TABLE "inventory_stock_moreStorageLocations" (
	"name"	TEXT,
	"locations"	TEXT,
	"locationID"	INTEGER NOT NULL UNIQUE,
	"capacity"	INTEGER,
	"currentStock"	INTEGER,
	"usage"	INTEGER,
	"manager"	TEXT,
	PRIMARY KEY("locationID")
);
CREATE TABLE orders_OrderItems (
    orderItemID INTEGER PRIMARY KEY AUTOINCREMENT,
    orderID INTEGER NOT NULL,
    productID INTEGER NOT NULL,
    itemName TEXT NOT NULL,
    quantity INTEGER NOT NULL DEFAULT 1,
    priceAtOrder REAL NOT NULL DEFAULT 0,
    FOREIGN KEY (orderID) REFERENCES orders_Orders(orderID)
        ON UPDATE CASCADE ON DELETE CASCADE,
    FOREIGN KEY (productID) REFERENCES product_Products(productID)
        ON UPDATE CASCADE ON DELETE RESTRICT
);
CREATE TABLE orders_Orders (
    orderID INTEGER PRIMARY KEY AUTOINCREMENT,
    customerID TEXT,
    customerName TEXT NOT NULL DEFAULT 'Guest',
    orderDate DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    status TEXT NOT NULL DEFAULT 'Pending',
    totalAmount REAL NOT NULL DEFAULT 0,
    FOREIGN KEY (customerID) REFERENCES customer_Customers(customerID)
        ON UPDATE CASCADE ON DELETE SET NULL
);
CREATE TABLE product_Category (
    categoryID INTEGER PRIMARY KEY AUTOINCREMENT,
    chosenSortBy TEXT NOT NULL DEFAULT '',
    chosenDietary TEXT NOT NULL,
    chosenHealthGoal TEXT NOT NULL,
    chosenCuisines TEXT NOT NULL,
    productID INTEGER NOT NULL UNIQUE,
    FOREIGN KEY (productID) REFERENCES product_Products(productID) ON UPDATE CASCADE ON DELETE CASCADE
);
CREATE TABLE product_Chef (
    chefID INTEGER PRIMARY KEY AUTOINCREMENT,
    chefName TEXT NOT NULL UNIQUE,
    "chefRating&ReviewID" INTEGER NOT NULL DEFAULT 0,
    chefDescription TEXT NOT NULL,
    chefTag1 TEXT NOT NULL DEFAULT '',
    chefTag2 TEXT NOT NULL DEFAULT '',
    chefTag3 TEXT NOT NULL DEFAULT '',
    chefImage TEXT NOT NULL DEFAULT '',
    chefEmail TEXT NOT NULL DEFAULT '',
    chefTel TEXT NOT NULL DEFAULT ''
);
CREATE TABLE product_ChefReview (
    reviewID INTEGER PRIMARY KEY AUTOINCREMENT,
    chefID INTEGER NOT NULL,
    reviewerName TEXT NOT NULL DEFAULT '',
    rating REAL NOT NULL DEFAULT 0 CHECK(rating BETWEEN 0 AND 5),
    reviewText TEXT NOT NULL DEFAULT '',
    reviewDate DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (chefID) REFERENCES product_Chef(chefID) ON UPDATE CASCADE ON DELETE CASCADE
);
CREATE TABLE product_DefaultIngredient (
    defaultIngredientID INTEGER PRIMARY KEY AUTOINCREMENT,
    defaultIngredients TEXT NOT NULL,
    totalCalories REAL NOT NULL DEFAULT 0,
    totalProtein REAL NOT NULL DEFAULT 0,
    totalCarbohydrates REAL NOT NULL DEFAULT 0,
    totalSugars REAL NOT NULL DEFAULT 0,
    totalFat REAL NOT NULL DEFAULT 0,
    totalSaturatedFat REAL NOT NULL DEFAULT 0,
    totalFiber REAL NOT NULL DEFAULT 0,
    totalSodium REAL NOT NULL DEFAULT 0,
    productID INTEGER NOT NULL,
    FOREIGN KEY (productID) REFERENCES product_Products(productID) ON UPDATE CASCADE ON DELETE CASCADE
);
CREATE TABLE product_Ingredient (
    ingredientID INTEGER PRIMARY KEY AUTOINCREMENT,
    ingredientName TEXT NOT NULL UNIQUE,
    calories REAL NOT NULL DEFAULT 0 CHECK(calories >= 0),
    protein REAL NOT NULL DEFAULT 0 CHECK(protein >= 0),
    carbohydrates REAL NOT NULL DEFAULT 0 CHECK(carbohydrates >= 0),
    sugars REAL NOT NULL DEFAULT 0 CHECK(sugars >= 0),
    fat REAL NOT NULL DEFAULT 0 CHECK(fat >= 0),
    saturatedFat REAL NOT NULL DEFAULT 0 CHECK(saturatedFat >= 0),
    fiber REAL NOT NULL DEFAULT 0 CHECK(fiber >= 0),
    sodium REAL NOT NULL DEFAULT 0 CHECK(sodium >= 0)
, imagePath TEXT);
CREATE TABLE product_ProductImage (
    imageID INTEGER PRIMARY KEY AUTOINCREMENT,
    imageURL TEXT NOT NULL,
    altText TEXT NOT NULL DEFAULT '',
    displayOrder INTEGER NOT NULL CHECK(displayOrder > 0),
    uploadDate DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    productID INTEGER NOT NULL,
    FOREIGN KEY (productID) REFERENCES product_Products(productID) ON UPDATE CASCADE ON DELETE CASCADE,
    UNIQUE(productID, displayOrder)
);
CREATE TABLE product_ProductIngredientOption (
    optionID INTEGER PRIMARY KEY AUTOINCREMENT,
    productID INTEGER NOT NULL,
    ingredientID INTEGER,
    optionGroup TEXT NOT NULL CHECK(optionGroup IN ('Base', 'Protein', 'Add-On')),
    optionName TEXT NOT NULL,
    extraPrice REAL NOT NULL DEFAULT 0 CHECK(extraPrice >= 0),
    selectedByDefault INTEGER NOT NULL DEFAULT 0 CHECK(selectedByDefault IN (0, 1)),
    allowMultiple INTEGER NOT NULL DEFAULT 1 CHECK(allowMultiple IN (0, 1)),
    status INTEGER NOT NULL DEFAULT 1 CHECK(status IN (0, 1)),
    FOREIGN KEY (productID) REFERENCES product_Products(productID) ON UPDATE CASCADE ON DELETE CASCADE,
    FOREIGN KEY (ingredientID) REFERENCES product_Ingredient(ingredientID) ON UPDATE CASCADE ON DELETE SET NULL,
    UNIQUE(productID, optionGroup, optionName)
);
CREATE TABLE product_Products (
    productID INTEGER PRIMARY KEY AUTOINCREMENT,
    productName TEXT NOT NULL UNIQUE,
    shortDescription TEXT NOT NULL,
    extendedDescription TEXT NOT NULL,
    cost REAL NOT NULL CHECK(cost >= 0),
    price REAL NOT NULL CHECK(price >= 0),
    status INTEGER NOT NULL DEFAULT 1 CHECK(status IN (0, 1)),
    spiceLevel INTEGER NOT NULL DEFAULT 0 CHECK(spiceLevel BETWEEN 0 AND 5),
    country TEXT NOT NULL,
    createdDate DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updatedDate DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    chefID INTEGER NOT NULL, sourceModule TEXT NOT NULL DEFAULT 'product', stockQuantity INTEGER NOT NULL DEFAULT 100,
    FOREIGN KEY (chefID) REFERENCES product_Chef(chefID) ON UPDATE CASCADE ON DELETE RESTRICT
);
